// =============================================================================
// NoFluffJobs Scraper — n8n Code Node (JavaScript)
// Metoda: HTML scraping + Angular SSR transfer-state JSON
// Interfejs: executeWorkflowTrigger → { max_pages?, config? }
// =============================================================================

const DEFAULT_CONFIG = {
  region:   "pl",
  maxPages: null,
  delayMs:  800,    // większy delay dla HTML scraping
  criteria: null,   // np. "backend" | "mobile" — doklejane do URL
};

// ── Helpers ──────────────────────────────────────────────────────────────────
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function normalizeSeniority(levels) {
  if (!levels || levels.length === 0) return null;
  const priority = ["expert", "lead", "manager", "senior", "mid", "junior"];
  for (const p of priority) {
    if (levels.map(l => l.toLowerCase()).includes(p)) return p;
  }
  return levels[0]?.toLowerCase() ?? null;
}

function parseLocation(raw) {
  // NFJ: raw.location = { places: [...], fullyRemote: bool, hybridDesc: string }
  const loc        = raw.location ?? {};
  const places     = loc.places ?? [];
  const fullyRemote = loc.fullyRemote ?? false;
  const hybridDesc  = (loc.hybridDesc ?? "").trim();

  let remote_type;
  if (fullyRemote)      remote_type = "remote";
  else if (hybridDesc)  remote_type = "hybrid";
  else                  remote_type = "office";

  const cities = places
    .filter(p => p.city && p.city !== "Remote")
    .map(p => p.city);

  let location;
  if (fullyRemote && cities.length === 0) location = "Remote";
  else if (cities.length > 0)             location = [...new Set(cities)].join(" / ");
  else                                    location  = null;

  return { location, remote_type };
}

function parseSalary(sal) {
  // NFJ: salary = { from?, to?, type, currency, disclosedAt, flexibleUpperBound }
  if (!sal || typeof sal !== "object") {
    return { salary_min: null, salary_max: null, salary_currency: null, salary_type: null };
  }
  return {
    salary_min:      sal.from     ?? null,
    salary_max:      sal.to       ?? null,
    salary_currency: sal.currency ?? null,
    salary_type:     sal.type?.toLowerCase() ?? null,
  };
}

function mapPosting(raw) {
  const { location, remote_type } = parseLocation(raw);
  const { salary_min, salary_max, salary_currency, salary_type } = parseSalary(raw.salary);

  // Tech stack: tiles.values[type==="requirement"] + raw.technology jako fallback
  const tileReqs = (raw.tiles?.values ?? [])
    .filter(t => t.type === "requirement")
    .map(t => t.value)
    .filter(Boolean);
  const techStack = raw.technology && !tileReqs.includes(raw.technology)
    ? [raw.technology, ...tileReqs]
    : tileReqs;

  const externalId = raw.id ?? null;
  const url        = externalId ? `https://nofluffjobs.com/pl/job/${externalId}` : null;
  const postedAt   = raw.posted  ? new Date(raw.posted).toISOString()  : null;
  const validUntil = raw.renewed ? new Date(raw.renewed).toISOString() : null;

  return {
    source:         "nofluffjobs",
    external_id:    externalId,
    url,
    title:          raw.title ?? null,
    company:        raw.name  ?? null,
    location,
    remote_type,
    salary_min,
    salary_max,
    salary_currency,
    salary_type,
    tech_stack:     techStack,
    seniority:      normalizeSeniority(raw.seniority),
    posted_at:      postedAt,
    valid_until:    validUntil,
    basic_payload:  raw,
  };
}

// ── Ekstrakcja danych z HTML ──────────────────────────────────────────────────
function extractFromHtml(html) {
  // Strategia 1: Angular SSR transfer state
  // <script id="serverApp-state" type="application/json">...</script>
  // Regex agnostyczny na kolejność atrybutów
  const ssrMatch = html.match(
    /<script\b[^>]*\bid=["']serverApp-state["'][^>]*>([\s\S]*?)<\/script>/i
  );

  if (ssrMatch) {
    try {
      const raw = ssrMatch[1]
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&amp;/g, "&")
        .replace(/&quot;/g, "\"")
        .replace(/&#39;/g, "'");

      const state = JSON.parse(raw);

      // Przeszukaj płytko i głęboko cały state szukając tablicy postings
      function findPostings(obj, depth = 0) {
        if (!obj || typeof obj !== "object" || depth > 5) return null;
        // bezpośrednie pola
        if (Array.isArray(obj.postings) && obj.postings.length > 0)
          return { postings: obj.postings, totalPages: obj.totalPages ?? null, totalCount: obj.totalCount ?? null };
        if (Array.isArray(obj.items) && obj.items.length > 0)
          return { postings: obj.items, totalPages: obj.totalPages ?? null, totalCount: obj.totalCount ?? null };
        // zagłębione (Angular HttpClient cache: { body: {...} })
        for (const val of Object.values(obj)) {
          const found = findPostings(val, depth + 1);
          if (found) return found;
        }
        return null;
      }

      const found = findPostings(state);
      if (found) return found;
    } catch (e) {
      // fall through do strategii 2
    }
  }

  // Strategia 2: window.__TRANSFER_STATE__ lub window.INITIAL_STATE lub podobne
  const windowStateMatch = html.match(
    /window\.__(?:TRANSFER_STATE|INITIAL_STATE|APP_STATE|NFJ_STATE)__\s*=\s*(\{[\s\S]*?\});\s*<\/script>/i
  );
  if (windowStateMatch) {
    try {
      const state = JSON.parse(windowStateMatch[1]);
      const postings = state.postings ?? state.items ?? state.jobs ?? null;
      if (postings && Array.isArray(postings)) {
        return { postings, totalPages: state.totalPages ?? null, totalCount: state.totalCount ?? null };
      }
    } catch (e) { /* fall through */ }
  }

  // Strategia 3: JSON-LD JobPosting schema
  const jsonLdMatches = [...html.matchAll(
    /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi
  )];
  const jobs = [];
  for (const m of jsonLdMatches) {
    try {
      const obj = JSON.parse(m[1]);
      const items = Array.isArray(obj) ? obj : [obj];
      for (const item of items) {
        if (item["@type"] === "JobPosting") jobs.push(item);
      }
    } catch (e) { /* skip */ }
  }
  if (jobs.length > 0) {
    return { postings: jobs, totalPages: null, totalCount: null, isJsonLd: true };
  }

  return null;
}

// Konwersja JSON-LD JobPosting → wspólny kontrakt (fallback)
function mapJsonLdPosting(raw) {
  const salary    = raw.baseSalary?.value ?? {};
  const url       = raw.url ?? null;
  const externalId = url ? url.split("/").pop() : null;

  return {
    source:         "nofluffjobs",
    external_id:    externalId,
    url,
    title:          raw.title ?? null,
    company:        raw.hiringOrganization?.name ?? null,
    location:       raw.jobLocation?.address?.addressLocality ?? null,
    remote_type:    raw.jobLocationType === "TELECOMMUTE" ? "remote" : "office",
    salary_min:     salary.minValue ?? null,
    salary_max:     salary.maxValue ?? null,
    salary_currency: raw.baseSalary?.currency ?? null,
    salary_type:    null,
    tech_stack:     [],
    seniority:      null,
    posted_at:      raw.datePosted ?? null,
    valid_until:    raw.validThrough ?? null,
    basic_payload:  raw,
  };
}

// ── Główna logika ─────────────────────────────────────────────────────────────
async function scrapeNoFluffJobs(cfg) {
  const results = [];
  let page = 1;
  let totalPages = null;

  const HEADERS = {
    "Accept":          "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "pl-PL,pl;q=0.9,en-US;q=0.8",
    "Accept-Encoding": "gzip, deflate, br",
    "User-Agent":      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Cache-Control":   "no-cache",
  };

  while (true) {
    if (cfg.maxPages !== null && page > cfg.maxPages) break;

    // URL: https://nofluffjobs.com/pl[/criteria]?page=N
    let pageUrl = `https://nofluffjobs.com/${cfg.region}`;
    if (cfg.criteria) pageUrl += `/${cfg.criteria}`;
    if (page > 1) pageUrl += `?page=${page}`;

    let html;
    try {
      html = await this.helpers.httpRequest({
        method:  "GET",
        url:     pageUrl,
        headers: HEADERS,
        json:    false,
      });
    } catch (err) {
      throw new Error(`NFJ fetch error (page ${page}, url: ${pageUrl}): ${err.message}`);
    }

    if (typeof html !== "string") {
      html = JSON.stringify(html);
    }

    const extracted = extractFromHtml(html);

    if (!extracted || extracted.postings.length === 0) {
      if (page === 1) {
        const ssrRawMatch = html.match(/<script\b[^>]*\bid=["']serverApp-state["'][^>]*>([\s\S]*?)<\/script>/i);
        const ssrRaw = ssrRawMatch ? ssrRawMatch[1].substring(0, 2000) : null;
        return [{
          json: {
            _debug:             true,
            html_length:        html.length,
            has_state_script:   html.includes("serverApp-state"),
            state_script_raw:   ssrRaw,       // surowa zawartość — co tu siedzi?
            html_end_2k:        html.substring(Math.max(0, html.length - 2000)),
          }
        }];
      }
      break;
    }

    if (totalPages === null) {
      totalPages = extracted.totalPages
        ?? (extracted.totalCount ? Math.ceil(extracted.totalCount / 20) : page + 1);
    }

    for (const raw of extracted.postings) {
      const mapped = extracted.isJsonLd ? mapJsonLdPosting(raw) : mapPosting(raw);
      results.push({ json: mapped });
    }

    if (page >= (totalPages ?? page)) break;

    page++;
    if (cfg.delayMs > 0) await sleep(cfg.delayMs);
  }

  return results;
}

// ── Wejście n8n ───────────────────────────────────────────────────────────────
const trigger  = $input.first().json ?? {};
const userConf = trigger.config ?? {};
const maxPages = trigger.max_pages ?? userConf.maxPages ?? DEFAULT_CONFIG.maxPages;

const cfg = { ...DEFAULT_CONFIG, ...userConf, maxPages };

return await scrapeNoFluffJobs.call(this, cfg);
